window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8e30dfafd447a597"]={"versions": [{"id": "FIG-8e30dfafd447a597", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Hardware-Architektur- und Topologiediagramm (UML-artiges Blockschaltbild) im Kontext des AUTOSAR ECU Resource Templates. Es illustriert die physische Anbindung mehrerer Verarbeitungseinheiten an eine gemeinsame Speicherressource innerhalb eines übergeordneten Hardware-Containers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>HW Container</strong>: Übergeordnete Hardware-Kapselungseinheit (ECU- bzw. Chip-Ebene).</li>\n<li><strong>PU 1, PU 2</strong>: Zwei diskrete Prozessoreinheiten (Processing Units / Cores) mit jeweils einem physischen Port / Bus-Interface.</li>\n<li><strong>Shared Memory</strong>: Gemeinsam genutzter Speicherblock mit zwei dedizierten Zugangs-Ports / Schnittstellen.</li>\n<li><strong>Conn_PU1</strong>: Punkt-zu-Punkt-Verbindungskanal zwischen dem Interface von <code>PU 1</code> und dem oberen Port des <code>Shared Memory</code>.</li>\n<li><strong>Conn_PU2</strong>: Punkt-zu-Punkt-Verbindungskanal zwischen dem Interface von <code>PU 2</code> und dem unteren Port des <code>Shared Memory</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Topologiemodell ohne explizite Zeit- oder Protokollsequenz. Die Kanäle ermöglichen den nebenläufigen oder gemultiplexten Lese- und Schreibzugriff beider Prozessoren (<code>PU 1</code>, <code>PU 2</code>) auf den adressierbaren Adressraum des <code>Shared Memory</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als exemplarisches Strukturmuster für die Modellierung von Multi-Core- bzw. Multi-Processor-Hardwareressourcen in AUTOSAR-Beschreibungsdateien (Resource Template). Bei der Software- und RTE-Konfiguration erfordern geteilte Speicherbereiche Mechanismen zur Zugriffssynchronisation (z. B. Spinlocks, Semaphoren oder Speicherschutz über MPU/MMU), um Dateninkonsistenzen bei parallelem Zugriff zu vermeiden.</p>"}, {"id": "FIG-89aa4e7f30054331", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Hardware-Architektur- und Topologiediagramm (UML-artiges Blockschaltbild) im Kontext des AUTOSAR ECU Resource Templates. Es illustriert die physische Anbindung mehrerer Verarbeitungseinheiten an eine gemeinsame Speicherressource innerhalb eines übergeordneten Hardware-Containers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>HW Container</strong>: Übergeordnete Hardware-Kapselungseinheit (ECU- bzw. Chip-Ebene).</li>\n<li><strong>PU 1, PU 2</strong>: Zwei diskrete Prozessoreinheiten (Processing Units / Cores) mit jeweils einem physischen Port / Bus-Interface.</li>\n<li><strong>Shared Memory</strong>: Gemeinsam genutzter Speicherblock mit zwei dedizierten Zugangs-Ports / Schnittstellen.</li>\n<li><strong>Conn_PU1</strong>: Punkt-zu-Punkt-Verbindungskanal zwischen dem Interface von <code>PU 1</code> und dem oberen Port des <code>Shared Memory</code>.</li>\n<li><strong>Conn_PU2</strong>: Punkt-zu-Punkt-Verbindungskanal zwischen dem Interface von <code>PU 2</code> und dem unteren Port des <code>Shared Memory</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Topologiemodell ohne explizite Zeit- oder Protokollsequenz. Die Kanäle ermöglichen den nebenläufigen oder gemultiplexten Lese- und Schreibzugriff beider Prozessoren (<code>PU 1</code>, <code>PU 2</code>) auf den adressierbaren Adressraum des <code>Shared Memory</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als exemplarisches Strukturmuster für die Modellierung von Multi-Core- bzw. Multi-Processor-Hardwareressourcen in AUTOSAR-Beschreibungsdateien (Resource Template). Bei der Software- und RTE-Konfiguration erfordern geteilte Speicherbereiche Mechanismen zur Zugriffssynchronisation (z. B. Spinlocks, Semaphoren oder Speicherschutz über MPU/MMU), um Dateninkonsistenzen bei parallelem Zugriff zu vermeiden.</p>"}], "trans": [{"from": "FIG-8e30dfafd447a597", "to": "FIG-89aa4e7f30054331", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
